 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('aac8d9ce-93b0-5bc5-a73f-9b0152c2e245',sid,'A treatise answering a published prediction of a planetary alignment, recalculating planetary positions on a geocentric model and arguing from gravitation against the predicted effects (as described in S1).','Critique of the 1919 planetary-alignment prediction (Mu''in-i-Mubin)','commentary_or_synthesis','medium',did,'1919','A prediction by Albert F. Porta, based on heliocentric astronomy (per S1).','A written response with its own geocentric calculation. Whether the calculation is sound has not been examined.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('aac8d9ce-93b0-5bc5-a73f-9b0152c2e245',(src->>'S1')::uuid,'pp. 62–66','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('27a51b83-da66-54fa-93a7-6206cde25d45',sid,'A book presenting 105 arguments, according to the author''s preface as quoted in S1, against the motion of the Earth, drawing on mathematics, philosophy, logic and the physics of his day. It is a historical argument. Modern astronomy establishes that the Earth rotates and orbits the Sun, so its conclusion is not part of modern astronomy.','Arguments against the Earth''s motion (Fauz-i-Mubin)','theoretical_contribution','medium',did,'1920 (per S1; date unresolved)','Copernican and Newtonian astronomy; earlier Muslim astronomical critique of Greek models (per S1).','A systematic polemical argument against Earth''s motion and against attraction/repulsion explanations. Originality of individual arguments is the author''s own claim and unverified.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('27a51b83-da66-54fa-93a7-6206cde25d45',(src->>'S1')::uuid,'pp. 67–73','academic_research');
